        int xor_result = static_cast<int>(message[i]) ^ rotated_mask;

        if (xor_result % 2 == 0) {
            checksum += xor_result;
        } else {
            checksum -= xor_result;
        }
    }

    // Combinatorial adjustment
    int combinatorial_factor = combination<10, 3>();
    int final_checksum = checksum % combinatorial_factor;

    // Encoding step
