int calculate_median(std::vector<int> data) {
    std::sort(data.begin(), data.end());
    size_t n = data.size();
    if (n % 2 == 0) {
        return (data[n/2 - 1] + data[n/2]) / 2;
    } else {
        return data[n/2];
    }
}

