#include <unordered_map>
#include <vector>
#include <functional>

int main() {
    // Packet priorities in a min-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> packet_queue;
    packet_queue.push(0b101010);
    packet_queue.push(0b111000);
    packet_queue.push(0b001100);

    // Filter rule lookup table
    std::unordered_map<int, bool> filter_rules = {{42, true}, {56, false}, {12, true}};

    int accumulator = 0;
    int processed_packets = 0;

    while (!packet_queue.empty() && processed_packets < 2) {
        int packet = packet_queue.top();
        packet_queue.pop();

        // Bitmask filter: check if bits 2 and 3 are set (0-indexed from right)
        bool bitmask_pass = (packet & 0b1100) == 0b1100;

        // Hash lookup filter
        bool hash_rule = filter_rules.count(packet) ? filter_rules[packet] : false;

        // Short-circuit logical evaluation: pass if bitmask passes OR (hash rule exists AND is true)
        bool packet_passes = bitmask_pass || (filter_rules.count(packet) && filter_rules[packet]);

        if (packet_passes) {
            // Apply bitwise transformation: XOR with 0xF and add to accumulator
            accumulator += (packet ^ 0xF);
        }

        processed_packets++;
    }

    // Final result combines accumulator with a bitwise operation
    int final_filter_result = (accumulator << 1) | 0b1;

    std::cout << "Result: " << final_filter_result << std::endl;
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define FIB_STEPS 6

typedef struct DigitWheel {
    int position;
    int history[];  // flexible array member
} DigitWheel;

typedef struct WheelNode {
    DigitWheel* wheel;
    int (*step_func)(int pos, int step_val);
    struct WheelNode* next;
} WheelNode;

int fibonacci(int n) {
    if (n <= 1) return n;
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int step_operation(int pos, int step_val) {
    return (pos + step_val) % 10;
}

int main() {
    int final_torque = 0;
    int num_wheels = 4;

    // Create linked list of wheels
    WheelNode* head = NULL;
    WheelNode* current = NULL;

    for (int i = 0; i < num_wheels; i++) {
        WheelNode* node = (WheelNode*)malloc(sizeof(WheelNode));
        size_t wheel_size = sizeof(DigitWheel) + FIB_STEPS * sizeof(int);
        node->wheel = (DigitWheel*)malloc(wheel_size);
        node->wheel->position = i + 1;
        node->step_func = step_operation;
        node->next = NULL;

        if (head == NULL) {
            head = node;
            current = node;
        } else {
            current->next = node;
            current = node;
        }
    }

    // Apply Fibonacci-based stepping
    current = head;
    int wheel_index = 0;
    while (current != NULL) {
        for (int step = 1; step <= FIB_STEPS; step++) {
            int fib_val = fibonacci(step);
            current->wheel->history[step-1] = current->wheel->position;
            current->wheel->position = current->step_func(current->wheel->position, fib_val);
        }
        final_torque += current->wheel->position * (wheel_index + 1);
        current = current->next;
        wheel_index++;
    }

    printf("Result: %d\n", final_torque);
    return 0;
}

