#include <iostream>
#include <string>
#include <functional>

class BracketTokenizer {
private:
    int nesting_depth;
    int innermost_count;

public:
    BracketTokenizer() : nesting_depth(0), innermost_count(0) {}

    // State machine for tracking bracket nesting
    void process_token(char token) {
        static enum { START, IN_BRACKET } state = START;

        switch(state) {
            case START:
                if (token == '[') {
                    nesting_depth++;
                    state = IN_BRACKET;
                }
                break;
            case IN_BRACKET:
                if (token == '[') {
                    nesting_depth++;
                } else if (token == ']') {
                    nesting_depth--;
                    if (nesting_depth == 0) {
                        // Potential innermost pair completed
                        if (is_balanced_pair()) {
                            innermost_count++;
                        }
                    }
                    if (nesting_depth <= 0) {
                        nesting_depth = 0;  // Reset if unbalanced
                        state = START;
                    }
                }
                break;
        }
    }

    // Recursive validation of bracket balance
    bool is_balanced_pair() {
        std::function<bool(int, const std::string&, size_t)> validate;
        validate = [&](int depth, const std::string& s, size_t index) -> bool {
            if (index >= s.length()) return depth == 0;
            if (s[index] == '[') return validate(depth + 1, s, index + 1);
            if (s[index] == ']') {
                if (depth <= 0) return false;
                return validate(depth - 1, s, index + 1);
            }
            return validate(depth, s, index + 1);  // Skip non-bracket chars
        };

        std::string test_str = "[[]]";
        return validate(0, test_str, 0);
    }

    int get_innermost_count() const { return innermost_count; }
};

int main() {
    BracketTokenizer tokenizer;
    std::string input_sequence = "[[[[][]]]][[][[]]]";

    for (char c : input_sequence) {
        tokenizer.process_token(c);
    }

    std::cout << "Result: " << tokenizer.get_innermost_count() << std::endl;
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_TASKS 100

typedef struct {
    int priority;
} Task;

typedef struct {
    Task* tasks;
    int size;
    int capacity;
} TaskHeap;

TaskHeap* create_heap(int capacity) {
    TaskHeap* heap = (TaskHeap*)malloc(sizeof(TaskHeap));
    heap->capacity = capacity;
    heap->size = 0;
    heap->tasks = (Task*)malloc(capacity * sizeof(Task));
    return heap;
}

void swap(Task* a, Task* b) {
    Task temp = *a;
    *a = *b;
    *b = temp;
}

void heapify_up(TaskHeap* heap, int index) {
    while (index > 0) {
        int parent = (index - 1) / 2;
        if (heap->tasks[index].priority <= heap->tasks[parent].priority)
            break;
        swap(&heap->tasks[index], &heap->tasks[parent]);
        index = parent;
    }
}

void heapify_down(TaskHeap* heap, int index) {
    while (1) {
        int left_child = 2 * index + 1;
        int right_child = 2 * index + 2;
        int largest = index;

        if (left_child < heap->size && heap->tasks[left_child].priority > heap->tasks[largest].priority)
            largest = left_child;
        if (right_child < heap->size && heap->tasks[right_child].priority > heap->tasks[largest].priority)
            largest = right_child;

        if (largest == index)
            break;

        swap(&heap->tasks[index], &heap->tasks[largest]);
        index = largest;
    }
}

void insert_task(TaskHeap* heap, int priority) {
    if (heap->size >= heap->capacity) return;
    heap->tasks[heap->size].priority = priority;
    heapify_up(heap, heap->size);
    heap->size++;
}

Task extract_max(TaskHeap* heap) {
    if (heap->size <= 0) {
        Task empty = {0};
        return empty;
    }
    Task max_task = heap->tasks[0];
    heap->tasks[0] = heap->tasks[heap->size - 1];
    heap->size--;
    heapify_down(heap, 0);
    return max_task;
}

int main() {
    TaskHeap* scheduler = create_heap(MAX_TASKS);

    // Insert initial tasks
    insert_task(scheduler, 15);
    insert_task(scheduler, 30);
    insert_task(scheduler, 10);
    insert_task(scheduler, 45);
    insert_task(scheduler, 20);

    // Extract the highest priority task
    extract_max(scheduler);

    // Insert new tasks
    insert_task(scheduler, 35);
    insert_task(scheduler, 5);

    // Extract another task
    extract_max(scheduler);

    // Final root priority after all operations
    int final_root_priority = scheduler->tasks[0].priority;

    printf("Result: %d\n", final_root_priority);

    free(scheduler->tasks);
    free(scheduler);

    return 0;
}

#include <iostream>
