    decoded_chars = []
    i = 0
    while i < len(verification_segment):
        count = 0
        while i < len(verification_segment) and verification_segment[i] == '1':
            count += 1
            i += 1
        if count > 0:
            # Find character with this code length
            for char, length in code_lengths.items():
                if length == count:
