void process_signal(int* start, int* end, int threshold) {
    if (start >= end) return;

    int* mid = start + (end - start) / 2;
    process_signal(start, mid, threshold);
    process_signal(mid + 1, end, threshold);

    if (start <= mid && mid < end) {
        if (*mid < threshold) {
            *mid = 0;
        }
        if (mid + 1 < end && *(mid + 1) < threshold) {
            *(mid + 1) = 0;
        }
    }
}

